use std::{
    env, fs,
    io::{self, Write},
    os::unix::{fs::symlink, process::ExitStatusExt},
    path::{Path, PathBuf},
    process::{Command, ExitStatus},
};

const REAL_CC: &str = "/usr/bin/cc";
const EXPECTED: &str = "/workspace/.cache/zed/target/debug/deps/koda-145bb81fa8b08935";
const PROBE: &str = "/workspace/android-studio-artifacts/module-presentation-integration/app-build/probe-output";
const OWNED_DIRECTORY: &str = "/tmp/android-studio-link-output";
const RECEIPTS: &str = "/workspace/android-studio-artifacts/module-presentation-integration/app-build";

fn json_string(value: &str) -> String {
    let mut result = String::from("\"");
    for character in value.chars() {
        match character {
            '"' => result.push_str("\\\""),
            '\\' => result.push_str("\\\\"),
            '\n' => result.push_str("\\n"),
            '\r' => result.push_str("\\r"),
            '\t' => result.push_str("\\t"),
            character if character.is_control() => {
                result.push_str(&format!("\\u{:04x}", character as u32));
            }
            character => result.push(character),
        }
    }
    result.push('"');
    result
}

fn exit_code(status: ExitStatus) -> i32 {
    status
        .code()
        .unwrap_or_else(|| 128 + status.signal().unwrap_or(1))
}

fn run() -> io::Result<i32> {
    let arguments: Vec<_> = env::args_os().skip(1).collect();
    let outputs: Vec<_> = arguments
        .windows(2)
        .enumerate()
        .filter(|(_, pair)| pair[0] == "-o")
        .map(|(index, pair)| (index + 1, PathBuf::from(&pair[1])))
        .collect();
    let selected = outputs.first().filter(|(_, output)| {
        outputs.len() == 1 && (output == Path::new(EXPECTED) || output == Path::new(PROBE))
    });
    let Some((output_index, original)) = selected else {
        return Command::new(REAL_CC)
            .args(&arguments)
            .status()
            .map(exit_code);
    };
    match fs::symlink_metadata(original) {
        Err(error) if error.kind() == io::ErrorKind::NotFound => {}
        Err(error) => return Err(error),
        Ok(_) => {
            return Err(io::Error::other(
                "refusing to replace an existing linker output",
            ))
        }
    }
    fs::create_dir_all(OWNED_DIRECTORY)?;
    let label = if original == Path::new(PROBE) {
        "probe"
    } else {
        "koda-module-presentation"
    };
    let redirected = Path::new(OWNED_DIRECTORY).join(format!("{label}-{}", std::process::id()));
    match fs::symlink_metadata(&redirected) {
        Err(error) if error.kind() == io::ErrorKind::NotFound => {}
        Err(error) => return Err(error),
        Ok(_) => return Err(io::Error::other("owned linker output already exists")),
    }
    let mut forwarded = arguments.clone();
    forwarded[*output_index] = redirected.clone().into_os_string();
    let code = exit_code(Command::new(REAL_CC).args(&forwarded).status()?);
    let arguments_json = |values: &[std::ffi::OsString]| {
        values
            .iter()
            .map(|value| json_string(&value.to_string_lossy()))
            .collect::<Vec<_>>()
            .join(",")
    };
    let receipt = format!(
        "{{\"real_cc\":{},\"original_output\":{},\"redirected_output\":{},\"exit_code\":{code},\"original_arguments\":[{}],\"forwarded_arguments\":[{}]}}\n",
        json_string(REAL_CC), json_string(&original.to_string_lossy()),
        json_string(&redirected.to_string_lossy()), arguments_json(&arguments), arguments_json(&forwarded)
    );
    let receipt_path = Path::new(RECEIPTS).join(format!("{label}-{}.json", std::process::id()));
    fs::OpenOptions::new()
        .write(true)
        .create_new(true)
        .open(receipt_path)?
        .write_all(receipt.as_bytes())?;
    if code != 0 {
        match fs::remove_file(&redirected) {
            Ok(()) => {}
            Err(error) if error.kind() == io::ErrorKind::NotFound => {}
            Err(error) => return Err(error),
        }
        return Ok(code);
    }
    if !fs::metadata(&redirected)?.is_file() {
        return Err(io::Error::other(
            "successful linker did not produce a regular file",
        ));
    }
    symlink(&redirected, original)?;
    Ok(0)
}

fn main() {
    match run() {
        Ok(code) => std::process::exit(code),
        Err(error) => {
            eprintln!("owned app link redirection failed: {error}");
            std::process::exit(1);
        }
    }
}
